package packages

import (
	"bytes"
	"fmt"
	"go/ast"
	"go/parser"
	"go/printer"
	"go/token"
	"path/filepath"
	"slices"
	"strconv"
	"strings"

	"golang.org/x/tools/go/ast/astutil"
)

// setAside loads again with the stale regenerated files of set replaced, in the
// two steps Load describes.
func setAside(patterns []string, cfg Config, set Set) (Set, error) {
	stale := staleFiles(set, cfg.Regenerated)
	if len(stale) == 0 {
		return set, nil
	}

	// A file that cannot be stubbed, such as one that no longer parses, is left
	// as it is here and emptied by the second step.
	overlay := make(map[string][]byte, len(stale))
	for _, f := range stale {
		if stub, ok := stubBodies(f.path); ok {
			overlay[f.path] = stub
		}
	}
	set, err := load(patterns, cfg, overlay)
	if err != nil {
		return Set{}, err
	}

	still := staleFiles(set, cfg.Regenerated)
	if len(still) == 0 {
		return set, nil
	}
	for _, f := range still {
		overlay[f.path] = fmt.Appendf(nil, "// Code generated by kanna. DO NOT EDIT.\n\npackage %s\n", f.pkg)
	}
	set, err = load(patterns, cfg, overlay)
	if err != nil {
		return Set{}, err
	}
	for _, f := range still {
		set.SetAside = append(set.SetAside, f.path)
	}
	return set, nil
}

// staleFile is a regenerated file that an error points into.
type staleFile struct {
	path string
	pkg  string // the package the file declares
}

// staleFiles lists the generated files in set, named one of regenerated, that an
// error points into, sorted by path.
func staleFiles(set Set, regenerated []string) []staleFile {
	broken := make(map[string]bool)
	for _, d := range set.Diags {
		broken[d.Pos.Filename] = true
	}

	var stale []staleFile
	for _, p := range set.Packages {
		for path := range GeneratedFiles(p) {
			if broken[path] && slices.Contains(regenerated, filepath.Base(path)) {
				stale = append(stale, staleFile{path: path, pkg: p.Name})
			}
		}
	}
	slices.SortFunc(stale, func(a, b staleFile) int { return strings.Compare(a.path, b.path) })
	return stale
}

// stubBodies returns the file at path with every function body replaced by a
// panic, or false when the file cannot be read as Go. An import that only the
// bodies used is renamed to _, or the stub would fail on it instead.
func stubBodies(path string) ([]byte, bool) {
	fset := token.NewFileSet()
	file, err := parser.ParseFile(fset, path, nil, parser.ParseComments)
	if err != nil {
		return nil, false
	}

	var bodies []*ast.BlockStmt
	for _, decl := range file.Decls {
		fn, ok := decl.(*ast.FuncDecl)
		if !ok || fn.Body == nil {
			continue
		}
		bodies = append(bodies, fn.Body)
		fn.Body = &ast.BlockStmt{List: []ast.Stmt{&ast.ExprStmt{X: &ast.CallExpr{
			Fun:  ast.NewIdent("panic"),
			Args: []ast.Expr{&ast.BasicLit{Kind: token.STRING, Value: strconv.Quote("stale")}},
		}}}}
	}

	// A comment from a dropped body would otherwise be printed somewhere else.
	file.Comments = slices.DeleteFunc(file.Comments, func(cg *ast.CommentGroup) bool {
		return slices.ContainsFunc(bodies, func(b *ast.BlockStmt) bool {
			return b.Pos() <= cg.Pos() && cg.End() <= b.End()
		})
	})

	for _, spec := range file.Imports {
		if p, err := strconv.Unquote(spec.Path.Value); err == nil && !astutil.UsesImport(file, p) {
			spec.Name = ast.NewIdent("_")
		}
	}

	var buf bytes.Buffer
	if err := printer.Fprint(&buf, fset, file); err != nil {
		return nil, false
	}
	return buf.Bytes(), true
}
